// This file is generated by AI.

// 配音工作台: 服务与启动配置、任务队列、角色库。
//
// 布局 (参考 WebGAL Terre 图形编辑器的语句面板: 分组紧凑、字段按内容宽度排布):
// ┌ 页头 ──────────────────────────────────────────────┐
// │ 配音工作台 · 说明副标题          [启动服务] [使用说明] │
// ├ 左栏 (配置) ─────────────┬ 右栏 (队列) ────────────┤
// │ 服务: 整合包 / 启动方式 / … │ 队列与日志 (独立滚动)    │
// │ 默认: 默认语言              │                         │
// ├───────────────────────────┴─────────────────────────┤
// │ 角色库 (占满剩余高度, 内部滚动)                        │
// └─────────────────────────────────────────────────────┘

import { Button, Field, Input, ProgressBar, Spinner, Textarea } from '@fluentui/react-components';
import {
  ArrowClockwiseRegular,
  BookQuestionMarkRegular,
  DismissRegular,
  ErrorCircleRegular,
  FolderOpenRegular,
  PlayRegular,
  StopRegular,
  WrenchRegular,
} from '@fluentui/react-icons';
import { open as openDialog } from '@tauri-apps/plugin-dialog';
import { revealItemInDir } from '@tauri-apps/plugin-opener';
import { useEffect, useState } from 'react';

import type { LaunchConfig } from '../commands/voice';
import { Select, toOptions } from '../components/Select';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';
import { formatEta } from './estimate';
import { RoleListPanel } from './RoleListPanel';
import { LANGUAGE_LABELS } from './types';
import { VoiceCacheDialog } from './VoiceCacheDialog';

export function VoiceWorkbench() {
  // 使用说明是独立选项卡, 直接由工作台发起打开
  const onOpenHelp = () => useAppStore.getState().openVoiceGuide();
  const status = useAppStore((state) => state.voiceStatus);
  const logs = useAppStore((state) => state.voiceLogs);
  useAppStore((state) => state.voiceTick);

  const settings = voiceController.getSettings();
  const [rootPath, setRootPath] = useState(settings.launch?.root ?? '');
  const [launch, setLaunch] = useState<LaunchConfig | null>(settings.launch);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [tab, setTab] = useState<'queue' | 'log'>('queue');
  const [changeDialogOpen, setChangeDialogOpen] = useState(false);

  const defaults = settings.defaults;
  const summary = voiceController.queueSummary();
  const running = status === 'ready' || status === 'starting';

  useEffect(() => {
    if (settings.launch) {
      setRootPath(settings.launch.root);
      setLaunch(settings.launch);
    }
  }, []);

  /** 更新并持久化启动配置 */
  const patchLaunch = (patch: Partial<LaunchConfig>) => {
    if (!launch) return;
    const next = { ...launch, ...patch };
    setLaunch(next);
    voiceController.updateSettings({ launch: next });
  };

  /** 选择整合包目录并探测 */
  const pickRoot = async () => {
    const selected = await openDialog({ directory: true, multiple: false });
    if (typeof selected !== 'string') return;
    setRootPath(selected);
    setBusy(true);
    setError(null);
    try {
      const config = await voiceController.detect(selected);
      setLaunch(config);
      voiceController.updateSettings({ launch: config });
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const start = async () => {
    if (!launch) {
      setError('请先选择 GPT-SoVITS 整合包目录');
      return;
    }
    setBusy(true);
    setError(null);
    try {
      await voiceController.startGsv(launch);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const stop = async () => {
    setBusy(true);
    try {
      await voiceController.stopGsv();
    } finally {
      setBusy(false);
    }
  };

  const statusLabel =
    status === 'ready' ? '就绪' : status === 'starting' ? '启动中…' : status === 'error' ? '错误' : '未启动';

  return (
    <div className="voice-workbench">
      {/* -------- 页头: 标题 + 主要操作 -------- */}
      <div className="voice-workbench-header">
        <div className="voice-workbench-heading">
          <h1>配音工作台</h1>
          <p>
            GPT-SoVITS 服务、角色库与任务队列
            <span className={`workbench-status workbench-status-${status}`}> · {statusLabel}</span>
          </p>
        </div>
        <div className="voice-workbench-actions">
          {running ? (
            <Button icon={<StopRegular />} disabled={busy} onClick={() => void stop()}>
              停止服务
            </Button>
          ) : (
            <Button appearance="primary" icon={<PlayRegular />} disabled={busy} onClick={() => void start()}>
              启动服务
            </Button>
          )}
          <Button appearance="secondary" icon={<BookQuestionMarkRegular />} onClick={onOpenHelp}>
            使用说明
          </Button>
        </div>
      </div>

      {/* -------- 左: 配置 / 右: 队列 -------- */}
      <div className="voice-workbench-columns">
        <section className="workbench-card workbench-config">
          <h2 className="workbench-card-title">服务配置</h2>

          <Field label="GPT-SoVITS 整合包目录" className="workbench-field-wide">
            <div className="workbench-input-row">
              <Input value={rootPath} readOnly placeholder="选择包含 api_v2.py 的整合包目录" />
              <Button appearance="secondary" onClick={() => void pickRoot()} disabled={busy}>
                选择…
              </Button>
              <Button
                appearance="subtle"
                title="在文件管理器中打开"
                icon={<FolderOpenRegular />}
                disabled={!rootPath}
                onClick={() => void revealItemInDir(rootPath)}
              />
            </div>
          </Field>

          {launch && (
            <>
              <div className="workbench-grid">
                <Field label="启动方式">
                  <Select
                    value={launch.mode.kind}
                    title={modeLabel(launch)}
                    options={[
                      { value: 'embedded', label: '整合包内置运行时' },
                      { value: 'python', label: '外部 Python' },
                      { value: 'command', label: '自定义命令' },
                    ]}
                    onChange={(kind) =>
                      patchLaunch({
                        mode:
                          kind === 'embedded'
                            ? { kind: 'embedded', program: `${launch.root}\\runtime\\python.exe` }
                            : kind === 'python'
                              ? { kind: 'python', program: 'python' }
                              : { kind: 'command', program: '', args: [] },
                      })
                    }
                  />
                </Field>

                <Field label={launch.mode.kind === 'command' ? '命令' : 'Python 解释器'}>
                  <Input
                    value={launch.mode.program}
                    onChange={(_, data) =>
                      patchLaunch({ mode: { ...launch.mode, program: data.value } as LaunchConfig['mode'] })
                    }
                  />
                </Field>

                <Field label="绑定地址">
                  <Input value={launch.host} onChange={(_, data) => patchLaunch({ host: data.value })} />
                </Field>

                <Field label="端口">
                  <Input
                    value={String(launch.port)}
                    onChange={(_, data) =>
                      patchLaunch({ port: Number.parseInt(data.value.replace(/[^0-9]/g, ''), 10) || 9880 })
                    }
                  />
                </Field>

                <Field label="控制脚本">
                  <Input value={launch.script} onChange={(_, data) => patchLaunch({ script: data.value })} />
                </Field>

                <Field label="推理配置">
                  <Input value={launch.inferConfig} onChange={(_, data) => patchLaunch({ inferConfig: data.value })} />
                </Field>
              </div>

              {launch.mode.kind === 'command' && (
                <Field label="命令参数（每行一个）">
                  <Textarea
                    className="workbench-args"
                    value={launch.mode.args.join('\n')}
                    resize="vertical"
                    onChange={(_, data) =>
                      patchLaunch({
                        mode: { ...launch.mode, args: data.value.split('\n').filter(Boolean) } as LaunchConfig['mode'],
                      })
                    }
                  />
                </Field>
              )}
            </>
          )}

          <h2 className="workbench-card-title">默认推理设置</h2>
          <div className="workbench-grid">
            <Field label="默认语言">
              <Select
                value={defaults.language}
                title="新对话默认使用的语言"
                options={toOptions(LANGUAGE_LABELS)}
                onChange={(language) => voiceController.updateSettings({ defaults: { ...defaults, language } })}
              />
            </Field>
          </div>

          {error && (
            <p className="voice-error">
              <ErrorCircleRegular /> {error}
            </p>
          )}
        </section>

        <section className="workbench-card workbench-queue">
          <div className="workbench-card-head">
            <h2 className="workbench-card-title">任务队列</h2>
            <div className="workbench-tabs">
              <button className={tab === 'queue' ? 'active' : ''} onClick={() => setTab('queue')}>
                队列
              </button>
              <button className={tab === 'log' ? 'active' : ''} onClick={() => setTab('log')}>
                日志
              </button>
            </div>
            <span className="workbench-spacer" />
            <Button
              size="small"
              appearance="subtle"
              title="清理未被任何场景引用的缓存音频"
              icon={<WrenchRegular />}
              onClick={() => setChangeDialogOpen(true)}
            />
            <Button
              size="small"
              appearance="subtle"
              title="清空已完成的任务"
              icon={<DismissRegular />}
              onClick={() => {
                voiceController.clearFinishedTasks();
                setTab('queue');
              }}
            />
          </div>

          <p className="workbench-summary">
            待处理 {summary.pending}（测试 {summary.pendingTest} · 生成 {summary.pendingGenerate}）
            {summary.running > 0 && ` · 运行中 ${summary.running}`}
            {summary.pending + summary.running > 0 && ` · 预计 ${formatEta(summary.etaMillis)}`}
          </p>

          {tab === 'queue' ? (
            <div className="workbench-scroll">
              {voiceController.allTasks().length === 0 && (
                <p className="voice-dialog-empty">队列为空。在场景卡的配音模式中点击「测试」或「生成」。</p>
              )}
              {voiceController.allTasks().map((task) => (
                <div key={task.id} className={`voice-task ${task.status}`}>
                  <span className={`history-kind ${task.kind}`}>{task.kind === 'test' ? '测试 x4' : '生成 x32'}</span>
                  <span className="voice-task-text">{task.text || '（空）'}</span>
                  <span className="voice-task-character">{task.characterName}</span>
                  <span className="voice-task-status">
                    {task.status === 'pending' && '等待中'}
                    {task.status === 'running' && (
                      <>
                        <Spinner size="extra-tiny" /> 生成中
                      </>
                    )}
                    {task.status === 'done' && '已完成'}
                    {task.status === 'failed' && <span className="voice-error">{task.error}</span>}
                    {task.status === 'canceled' && '已取消'}
                  </span>
                  {task.status === 'running' && <ProgressBar />}
                </div>
              ))}
            </div>
          ) : (
            <div className="workbench-scroll workbench-log">
              {logs.length === 0 && <p className="voice-dialog-empty">暂无日志。</p>}
              {logs.map((line, index) => (
                <div key={index} className="voice-log-line">
                  {line}
                </div>
              ))}
              <Button
                size="small"
                appearance="subtle"
                icon={<ArrowClockwiseRegular />}
                onClick={() => void voiceController.syncStatus()}
              >
                刷新
              </Button>
            </div>
          )}
        </section>
      </div>

      {/* -------- 角色库: 占满剩余高度 -------- */}
      <RoleListPanel />

      <VoiceCacheDialog open={changeDialogOpen} onClose={() => setChangeDialogOpen(false)} />
    </div>
  );
}

function modeLabel(launch: LaunchConfig): string {
  switch (launch.mode.kind) {
    case 'embedded':
      return '整合包内置运行时';
    case 'python':
      return '外部 Python（conda / 系统）';
    default:
      return '自定义命令（bat / ps1 / 可执行文件）';
  }
}
